import{_ as t,o as a,c as u,a3 as o}from"./chunks/framework.DX_KL3e0.js";const d=JSON.parse('{"title":"Duyệt yêu cầu (Quản lý)","description":"","frontmatter":{},"headers":[],"relativePath":"huong-dan/duyet-yeu-cau.md","filePath":"huong-dan/duyet-yeu-cau.md","lastUpdated":1783009205000}'),g={name:"huong-dan/duyet-yeu-cau.md"};function e(r,n,c,i,h,s){return a(),u("div",null,[...n[0]||(n[0]=[o('<h1 id="duyet-yeu-cau-quan-ly" tabindex="-1">Duyệt yêu cầu (Quản lý) <a class="header-anchor" href="#duyet-yeu-cau-quan-ly" aria-label="Permalink to &quot;Duyệt yêu cầu (Quản lý)&quot;">​</a></h1><blockquote><p><strong>🎯 Mục tiêu:</strong> Duyệt bù công / tăng ca / nghỉ phép và đề xuất xóa tài sản. <strong>👤 Ai làm được:</strong> Quản Lý — Super Admin, Admin, Manager. (Manager chỉ thấy yêu cầu của <strong>đội mình</strong>.)</p></blockquote><h2 id="duyet-cong-bu-cong-·-tang-ca-·-nghi-phep" tabindex="-1">Duyệt Công (bù công · tăng ca · nghỉ phép) <a class="header-anchor" href="#duyet-cong-bu-cong-·-tang-ca-·-nghi-phep" aria-label="Permalink to &quot;Duyệt Công (bù công · tăng ca · nghỉ phép)&quot;">​</a></h2><ol><li>Vào <strong>Duyệt Yêu Cầu</strong> → thẻ <strong>Duyệt Công</strong>.</li><li>Chọn tab: <strong>Bù Công</strong> · <strong>Tăng Ca</strong> · <strong>Nghỉ Phép</strong>.</li><li>Xem chi tiết (người gửi, ngày/giờ, số công/giờ, lý do); nhập <strong>ghi chú / phản hồi</strong> nếu cần.</li><li>Bấm <strong>Duyệt</strong> để chấp thuận, hoặc <strong>Từ chối</strong> / <strong>Yêu Cầu Sửa</strong> để trả lại.</li></ol><p>→ Sau khi duyệt, <strong>dữ liệu công của nhân viên cập nhật tự động</strong>.</p><div class="tip custom-block"><p class="custom-block-title">Xem bảng công đội ngũ</p><p>Bảng công <strong>không còn duyệt thủ công</strong> (tự gửi khi tới hạn). Quản lý xem bảng công cấp dưới — nhóm theo Công ty/Phòng ban, có tìm kiếm &amp; lọc — tại <strong>Dữ Liệu Chấm Công → Bảng Công</strong>.</p></div><h2 id="duyet-xoa-tai-san-chi-super-admin" tabindex="-1">Duyệt Xóa Tài Sản (chỉ Super Admin) <a class="header-anchor" href="#duyet-xoa-tai-san-chi-super-admin" aria-label="Permalink to &quot;Duyệt Xóa Tài Sản (chỉ Super Admin)&quot;">​</a></h2><p>Vào <strong>Duyệt Yêu Cầu → Duyệt Xóa Tài Sản</strong> → xem đề xuất → <strong>Phê duyệt</strong> hoặc <strong>Từ chối</strong>.</p><h2 id="💡-meo" tabindex="-1">💡 Mẹo <a class="header-anchor" href="#💡-meo" aria-label="Permalink to &quot;💡 Mẹo&quot;">​</a></h2><p>Với một số luồng (vd đặt phòng họp), bạn có thể <strong>duyệt nhanh ngay trên Telegram</strong> bằng nút ✅ Duyệt / ❌ Từ chối, không cần mở web.</p><p><em>Chi tiết: <a href="/help/chuc-nang/duyet-yeu-cau.html">Duyệt yêu cầu</a></em></p>',11)])])}const p=t(g,[["render",e]]);export{d as __pageData,p as default};
